    input         clk,
    input  [15:0] inM,
    input  [15:0] instruction,
    input         reset,
    output reg [15:0] outM,
    output        writeM,
    output [14:0] addressM,
    output [14:0] pc
);
    // 测试台按层级路径读取 cpu.a_reg / cpu.d_reg / cpu.pc_reg，
    // 请保留这三个寄存器命名（对应课程中的 ARegister / DRegister / PC）。
